window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-932adf6827461e76"]={"versions": [{"id": "FIG-932adf6827461e76", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Architektur-Kategoriendiagramm der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Zuordnung und Gruppierung von funktionalen Clustern (<em>Functional Clusters</em>) zur Architektur-Kategorie <strong>Communication</strong> gemäß <code>AUTOSAR_EXP_SWArchitecture</code> (Release R22-11).\n</li><li><strong>Architektonische Einordnung:</strong> Definiert die Basisinfrastruktur für dienstorientierte Kommunikation (Service-Oriented Communication), Netzwerkzustandsverwaltung (Partial Networking, Bus-Sleep/Wake-up) und netzwerkweite Taktsynchronisation auf POSIX-basierten Adaptive-Steuergeräten.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert drei funktionale Einheiten mit dem AUTOSAR-Stereotyp <code>«aapFunctionalCluster»</code>:</p>\n<ol class=\"fig-list\"><li><strong><code>Communication Management</code> (<code>ara::com</code>):</strong>\n<ul class=\"fig-list\"><li>Stellt die dienstorientierte Middleware-Abstraktion bereit (Events, Methods, Fields).\n</li><li>Realisiert Inter-Process Communication (IPC) sowie fahrzeugweite Netzwerkanbindungen (z. B. SOME/IP, DDS, Signal-to-Service).\n</li><li>Architekturtypisch primär als Link-Bibliothek (<em>library-based</em>) direkt im Adressraum der Adaptive Applications implementiert.\n</li></ul>\n</li><li><strong><code>Network Management</code> (<code>ara::nm</code>):</strong>\n<ul class=\"fig-list\"><li>Koordiniert Netzwerkzustände (z. B. <em>Repeat Message</em>, <em>Normal Operation</em>, <em>Ready Sleep</em>) und Partielle Netzwerke (PN).\n</li><li>Stellt Schnittstellen zur Anforderung und Freigabe von Kommunikationskanälen bereit.\n</li></ul>\n</li><li><strong><code>Time Synchronization</code> (<code>ara::tsync</code>):</strong>\n<ul class=\"fig-list\"><li>Bereitstellung synchronisierter Zeitbasen über Zeitdomänen hinweg (z. B. synchronisierte Fahrzeugzeit nach IEEE 802.1AS / gPTP, IEEE 1588 oder CAN-TSyn).\n</li><li><strong>Stereotyp/Annotation:</strong> Explizit als <code>daemon-based</code> klassifiziert. Läuft zwingend als eigenständiger Systemprozess (POSIX-Daemon) im Hintergrund, um Takt-Frames kontinuierlich auf OS-/Netzwerktreiberebene zu terminieren und Uhren-Disziplinierung vorzunehmen.\n</li></ul>\n</li></ol>\n<p class=\"fig-p\"><em>Beziehungen &amp; Konnektoren:</em> Keine expliziten Ports, Abhängigkeiten oder Schnittstellenrelationen im Diagramm dargestellt; es handelt sich um eine reine Kategorienschnitt-Taxonomie.</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammart:</strong> Rein statisches Deklarationsdiagramm; enthält keine Sequenz-, Timing- oder Kontrollfluss-Pfade.\n</li><li><strong>Laufzeit-Dynamik im Gesamtsystem:</strong>\n<ul class=\"fig-list\"><li><code>ara::tsync</code> agiert als autonomer Daemon, empfängt periodische Zeit-Pakete, nutzt Hardware-/Kernel-Timestamping und aktualisiert Zeitbasen, die Applikationen über IPC/Shared Memory synchron abrufen.\n</li><li><code>ara::nm</code> synchronisiert zyklische NM-Botschaften über den Bus und triggert Zustandswechsel.\n</li><li><code>ara::com</code> überträgt Nutzdaten asynchron oder synchron erst, wenn <code>ara::nm</code> den betreffenden Netzwerkkanal freigegeben hat.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Prozess- &amp; Deployment-Modell:</strong>\n<ul class=\"fig-list\"><li>Für <code>Time Synchronization</code> muss ein separates POSIX-Executable im <em>Execution Manifest</em> konfiguriert werden, das mit entsprechenden OS-Privilegien (z. B. <code>CAP_SYS_TIME</code>, Zugriff auf PTP Hardware Clock <code>/dev/ptp*</code>) durch das <em>Execution Management</em> (<code>ara::exec</code>) gestartet wird.\n</li><li><code>Communication Management</code> erfordert typischerweise kein eigenständiges Daemon-Deployment für die Kern-API, sondern bindet sich als Laufzeitbibliothek in die Applikationsprozesse ein (abgesehen von optionalen, herstellerspezifischen IPC-Routern oder Binding-Daemons).\n</li></ul>\n</li><li><strong>Konfigurations-Vertrag (ARXML):</strong>\n<ul class=\"fig-list\"><li>Dienst- und Netzwerkschnittstellen müssen im <em>Service Instance Manifest</em> (<code>ServiceInstanceToMachineMapping</code>) und <em>Network Manifest</em> exakt aufeinander abgestimmt sein.\n</li><li>NM-Cluster-Zustände müssen an die entsprechenden Network-Handles gekoppelt werden; fehlerhafte Synchronisation zwischen <code>ara::com</code>-Dienstaufrufen und <code>ara::nm</code>-Freigaben führt zu stillem Paketverlust auf Bus-Ebene.\n</li></ul>\n</li></ul>"}, {"id": "FIG-4030e66056c17695", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Architektur-Kategoriendiagramm der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Zuordnung und Gruppierung von funktionalen Clustern (<em>Functional Clusters</em>) zur Architektur-Kategorie <strong>Communication</strong> gemäß <code>AUTOSAR_EXP_SWArchitecture</code>.\n</li><li><strong>Architektonische Einordnung:</strong> Definiert die Basisinfrastruktur für dienstorientierte Kommunikation (Service-Oriented Communication), ungepufferte Hochdurchsatz-Rohdatenströme (Raw Data Stream), Netzwerkzustandsverwaltung (Partial Networking, Bus-Sleep/Wake-up) und netzwerkweite Taktsynchronisation auf POSIX-basierten Adaptive-Steuergeräten.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert vier funktionale Einheiten mit dem AUTOSAR-Stereotyp <code>«aapFunctionalCluster»</code>:</p>\n<ol class=\"fig-list\"><li><strong><code>Communication Management</code> (<code>ara::com</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> Explizit als <code>daemon-based</code> klassifiziert. Beinhaltet Hintergrund-Dienste (z. B. SOME/IP-Daemon, Service Discovery, IPC-Routing).\n</li><li>Stellt die dienstorientierte Middleware-Abstraktion bereit (Events, Methods, Fields) für Inter-Process Communication (IPC) sowie netzwerkweite Kommunikation.\n</li></ul>\n</li><li><strong><code>Raw Data Stream</code>:</strong>\n<ul class=\"fig-list\"><li>Bibliotheksbasiert (keine Annotation; neu hinzugefügter Cluster).\n</li><li>Bietet Schnittstellen für hochperformante, unstrukturierte Rohdatenströme (z. B. Sensor-, Kamera- oder Audio-/Videodaten) mit minimalem Overhead außerhalb der serviceorientierten Middleware.\n</li></ul>\n</li><li><strong><code>Network Management</code> (<code>ara::nm</code>):</strong>\n<ul class=\"fig-list\"><li>Bibliotheksbasiert (keine Annotation).\n</li><li>Koordiniert Netzwerkzustände (z. B. <em>Repeat Message</em>, <em>Normal Operation</em>, <em>Ready Sleep</em>) und Partielle Netzwerke (PN).\n</li><li>Stellt Schnittstellen zur Anforderung und Freigabe von Kommunikationskanälen bereit.\n</li></ul>\n</li><li><strong><code>Time Synchronization</code> (<code>ara::tsync</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> Explizit als <code>daemon-based</code> klassifiziert.\n</li><li>Läuft als eigenständiger Systemprozess (POSIX-Daemon) im Hintergrund, um Takt-Frames kontinuierlich auf OS-/Netzwerktreiberebene zu terminieren und Zeitbasen über Zeitdomänen hinweg (z. B. gPTP nach IEEE 802.1AS) zu synchronisieren.\n</li></ul>\n</li></ol>\n<p class=\"fig-p\"><em>Beziehungen &amp; Konnektoren:</em> Keine expliziten Ports, Abhängigkeiten oder Schnittstellenrelationen im Diagramm dargestellt; es handelt sich um eine reine Kategorienschnitt-Taxonomie.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammart:</strong> Rein statisches Deklarationsdiagramm; enthält keine Sequenz-, Timing- oder Kontrollfluss-Pfade.\n</li><li><strong>Laufzeit-Dynamik im Gesamtsystem:</strong>\n<ul class=\"fig-list\"><li><code>Communication Management</code> nutzt Hintergrund-Daemons für Service Discovery (FindService/OfferService) sowie das Routing und Serialisieren von Botschaften über Bus- und IPC-Grenzen hinweg.\n</li><li><code>Raw Data Stream</code> stellt kontinuierliche Datenkanäle bereit, über die Streaming-Endpunkte große Nutzdatenblöcke effizient zwischen Applikationen oder Netzwerktreibern transferieren.\n</li><li><code>ara::tsync</code> agiert als autonomer Daemon, empfängt periodische Zeit-Pakete, nutzt Hardware-/Kernel-Timestamping und aktualisiert Zeitbasen im Shared Memory.\n</li><li><code>ara::nm</code> synchronisiert zyklische NM-Botschaften über den Bus und steuert Kanalzustände, bevor Nutzdatenflüsse freigegeben werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Prozess- &amp; Deployment-Modell:</strong>\n<ul class=\"fig-list\"><li>Sowohl <code>Communication Management</code> als auch <code>Time Synchronization</code> sind als <code>daemon-based</code> annotiert; für beide müssen eigenständige Executables im <em>Execution Manifest</em> deklariert und durch das <em>Execution Management</em> (<code>ara::exec</code>) instanziiert werden.\n</li><li><code>Raw Data Stream</code> und <code>Network Management</code> sind bibliotheksbasiert und werden direkt in den Prozesskontext der nutzenden Adaptive Applications gelinkt.\n</li></ul>\n</li><li><strong>Konfigurations-Vertrag (ARXML):</strong>\n<ul class=\"fig-list\"><li>Dienst- und Netzwerkschnittstellen müssen im <em>Service Instance Manifest</em> (<code>ServiceInstanceToMachineMapping</code>) und <em>Network Manifest</em> exakt aufeinander abgestimmt sein.\n</li><li>Für <code>Raw Data Stream</code> sind Streaming-Ports, Transportprotokolle und Pufferstrukturen in den Manifesten zu spezifizieren.\n</li><li>NM-Cluster-Zustände müssen an die entsprechenden Network-Handles gekoppelt werden; fehlerhafte Synchronisation zwischen <code>ara::com</code>-Dienstaufrufen, Streaming-Kanälen und <code>ara::nm</code>-Freigaben führt zu stillem Paketverlust auf Bus-Ebene.\n</li></ul>\n</li></ul>"}, {"id": "FIG-3bbfc4576980545a", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Architektur-Kategoriendiagramm der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Zuordnung und Gruppierung von funktionalen Clustern (<em>Functional Clusters</em>) zur Architektur-Kategorie <strong>Communication</strong> gemäß <code>AUTOSAR_EXP_SWArchitecture</code>.\n</li><li><strong>Architektonische Einordnung:</strong> Definiert die Basisinfrastruktur für dienstorientierte Kommunikation (Service-Oriented Communication), standardisierte fahrzeugweite API-Gateways (Automotive API Gateway), ungepufferte Rohdatenströme (Raw Data Stream), Netzwerkzustandsverwaltung (Partial Networking) und netzwerkweite Taktsynchronisation auf POSIX-basierten Adaptive-Steuergeräten.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert fünf funktionale Einheiten mit dem AUTOSAR-Stereotyp <code>«aapFunctionalCluster»</code>:</p>\n<ol class=\"fig-list\"><li><strong><code>Communication Management</code> (<code>ara::com</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> <code>daemon-based</code>.\n</li><li>Stellt die dienstorientierte Middleware-Abstraktion bereit (Events, Methods, Fields) für IPC und fahrzeugweite Kommunikation.\n</li></ul>\n</li><li><strong><code>Raw Data Stream</code>:</strong>\n<ul class=\"fig-list\"><li>Bibliotheksbasiert (keine Annotation).\n</li><li>Stellt Schnittstellen für kontinuierliche, latenzarme Rohdatenströme (z. B. Sensor-, Video- oder Streamingdaten) bereit.\n</li></ul>\n</li><li><strong><code>Network Management</code> (<code>ara::nm</code>):</strong>\n<ul class=\"fig-list\"><li>Bibliotheksbasiert (keine Annotation).\n</li><li>Koordiniert Netzwerkzustände (Repeat Message, Normal Operation, Ready Sleep) und Partielle Netzwerke (PN).\n</li></ul>\n</li><li><strong><code>Time Synchronization</code> (<code>ara::tsync</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> <code>daemon-based</code>.\n</li><li>Bereitstellung synchronisierter Zeitbasen über Zeitdomänen hinweg (gPTP / IEEE 802.1AS, CAN-TSyn).\n</li></ul>\n</li><li><strong><code>Automotive API Gateway</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> <code>daemon-based</code> (neu hinzugefügt in einer zweiten Zeile unterhalb von Communication Management).\n</li><li>Agiert als Gateway und Protokollumsetzer zwischen externen/standardisierten Fahrzeug-APIs (z. B. REST, WebSocket, COVESA Vehicle Signal Specification) und den internen Adaptive-Plattformdiensten.\n</li></ul>\n</li></ol>\n<p class=\"fig-p\"><em>Beziehungen &amp; Konnektoren:</em> Keine expliziten Ports, Abhängigkeiten oder Schnittstellenrelationen im Diagramm dargestellt; rein deklarative Kategorienschnitt-Taxonomie.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammart:</strong> Rein statisches Deklarationsdiagramm; enthält keine Sequenz-, Timing- oder Kontrollfluss-Pfade.\n</li><li><strong>Laufzeit-Dynamik im Gesamtsystem:</strong>\n<ul class=\"fig-list\"><li><code>Automotive API Gateway</code> nimmt als Hintergrund-Daemon externe API-Anfragen entgegen, transformiert diese in standardisierte <code>ara::com</code>-Methodenaufrufe oder Feldbeschreibungen und leitet Antworten bzw. Ereignisse bidirektional weiter.\n</li><li><code>Communication Management</code> vermittelt Service Discovery, IPC und Netzwerk-Bindings.\n</li><li><code>Raw Data Stream</code> wickelt hochvolumige Datenübertragungen ohne Middleware-Serialisierung ab.\n</li><li><code>ara::tsync</code> synchronisiert Takte autonom im Hintergrund via Hardware-/Kernel-Timestamping.\n</li><li><code>ara::nm</code> schaltet Netzwerk- und Kanalzustände bedarfsgerecht aktiv oder versetzt sie in den Schlafzustand.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Prozess- &amp; Deployment-Modell:</strong>\n<ul class=\"fig-list\"><li><code>Communication Management</code>, <code>Time Synchronization</code> und <code>Automotive API Gateway</code> sind als <code>daemon-based</code> annotiert und erfordern eigenständige POSIX-Executables im <em>Execution Manifest</em>, die von <code>ara::exec</code> überwacht und gestartet werden.\n</li><li>Für das <code>Automotive API Gateway</code> sind IP-Endpunkte, Portbindungen und Zugriffskontrollen (z. B. TLS, Authentifizierung und Berechtigungen via Identity and Access Management) zu konfigurieren.\n</li><li><code>Raw Data Stream</code> und <code>Network Management</code> verbleiben bibliotheksbasiert.\n</li></ul>\n</li><li><strong>Konfigurations-Vertrag (ARXML):</strong>\n<ul class=\"fig-list\"><li>Mappings von externen Fahrzeug-API-Modellen auf interne Service-Interfaces (<code>ServiceInterface</code>) müssen im Konfigurationsmanifest des Gateways hinterlegt werden.\n</li><li>Dienst- und Netzwerkschnittstellen müssen im <em>Service Instance Manifest</em> und <em>Network Manifest</em> aufeinander abgestimmt sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-8206c96d6df536fd", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Architektur-Kategoriendiagramm der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Deklarative Zuordnung und Gruppierung von funktionalen Clustern (<em>Functional Clusters</em>) zur Architektur-Kategorie <strong>Communication</strong> gemäß <code>AUTOSAR_EXP_SWArchitecture</code>.\n</li><li><strong>Architektonische Einordnung:</strong> Definiert die Basisinfrastruktur für dienstorientierte Kommunikation (Service-Oriented Communication), standardisierte fahrzeugweite API-Gateways (Automotive API Gateway), ungepufferte Rohdatenströme (Raw Data Stream), Netzwerkzustandsverwaltung (Partial Networking) und netzwerkweite Taktsynchronisation auf POSIX-basierten Adaptive-Steuergeräten.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert fünf funktionale Einheiten mit dem AUTOSAR-Stereotyp <code>«aapFunctionalCluster»</code>:</p>\n<ol class=\"fig-list\"><li><strong><code>Communication Management</code> (<code>ara::com</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> <code>daemon-based</code>.\n</li><li>Stellt die dienstorientierte Middleware-Abstraktion bereit (Events, Methods, Fields).\n</li></ul>\n</li><li><strong><code>Raw Data Stream</code>:</strong>\n<ul class=\"fig-list\"><li>Bibliotheksbasiert (keine Annotation; einzig verbliebenes rein bibliotheksbasiertes Cluster der Kategorie).\n</li><li>Stellt Schnittstellen für latenzarme, ungepufferte Rohdatenübertragungen bereit.\n</li></ul>\n</li><li><strong><code>Network Management</code> (<code>ara::nm</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> <code>daemon-based</code> (Status von bibliotheksbasiert auf Daemon-basiert geändert).\n</li><li>Läuft nun als eigenständiger Systemprozess zur Verwaltung von Netzwerkzuständen (Repeat Message, Normal Operation, Ready Sleep) und Partiellen Netzwerken (PN).\n</li></ul>\n</li><li><strong><code>Time Synchronization</code> (<code>ara::tsync</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> <code>daemon-based</code>.\n</li><li>Bereitstellung synchronisierter Zeitbasen (gPTP, CAN-TSyn).\n</li></ul>\n</li><li><strong><code>Automotive API Gateway</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Stereotyp/Annotation:</strong> <code>daemon-based</code>.\n</li><li>Protokoll- und API-Gateway zur Übersetzung externer/standardisierter Fahrzeug-APIs in interne Plattform-Dienste.\n</li></ul>\n</li></ol>\n<p class=\"fig-p\"><em>Beziehungen &amp; Konnektoren:</em> Keine expliziten Ports, Abhängigkeiten oder Schnittstellenrelationen im Diagramm dargestellt; rein deklarative Kategorienschnitt-Taxonomie.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammart:</strong> Rein statisches Deklarationsdiagramm; enthält keine Sequenz-, Timing- oder Kontrollfluss-Pfade.\n</li><li><strong>Laufzeit-Dynamik im Gesamtsystem:</strong>\n<ul class=\"fig-list\"><li><code>Automotive API Gateway</code> nimmt als Hintergrund-Daemon externe API-Anfragen entgegen, transformiert diese in standardisierte <code>ara::com</code>-Methodenaufrufe oder Feldbeschreibungen und leitet Antworten bzw. Ereignisse bidirektional weiter.\n</li><li><code>Communication Management</code> vermittelt Service Discovery, IPC und Netzwerk-Bindings.\n</li><li><code>Raw Data Stream</code> wickelt hochvolumige Datenübertragungen ohne Middleware-Serialisierung ab.\n</li><li><code>ara::tsync</code> synchronisiert Takte autonom im Hintergrund via Hardware-/Kernel-Timestamping.\n</li><li><code>ara::nm</code> schaltet Netzwerk- und Kanalzustände bedarfsgerecht aktiv oder versetzt sie in den Schlafzustand.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Prozess- &amp; Deployment-Modell:</strong>\n<ul class=\"fig-list\"><li>Vier der fünf funktionalen Cluster (<code>Communication Management</code>, <code>Network Management</code>, <code>Time Synchronization</code> und <code>Automotive API Gateway</code>) sind nun als <code>daemon-based</code> ausgewiesen.\n</li><li>Für <code>Network Management</code> muss nun zwingend ein separates POSIX-Executable im <em>Execution Manifest</em> definiert werden, das mit entsprechenden Rechten zur Kommunikation auf Socket-/CAN-Ebene durch <code>ara::exec</code> gestartet wird; Applikationen binden lediglich schlanke NM-Client-Bibliotheken ein.\n</li><li><code>Raw Data Stream</code> verbleibt als einziger Cluster rein bibliotheksbasiert.\n</li></ul>\n</li><li><strong>Konfigurations-Vertrag (ARXML):</strong>\n<ul class=\"fig-list\"><li>NM-Daemon-Instanzen müssen den konfigurierten Network-Handles und partiellen Netzwerkclustern im <em>Network Management Manifest</em> exakt zugeordnet sein.\n</li><li>Gateway- und Service-Manifeste bleiben konsistent zu den Service- und Netzwerkkonfigurationen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-932adf6827461e76", "to": "FIG-4030e66056c17695", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Communication Management</code>: Annotation <code>daemon-based</code> neu hinzugefügt (Umstellung des Prozess- und Ausführungsmodells von rein bibliotheksbasiert auf Daemon-basiert).\n</li><li><code>«aapFunctionalCluster» Raw Data Stream</code>: Neuer funktionaler Cluster in der Kategorie Communication ergänzt (bibliotheksbasiert).\n</li></ul>"}, {"from": "FIG-4030e66056c17695", "to": "FIG-3bbfc4576980545a", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Automotive API Gateway</code>: Neuer funktionaler Cluster mit der Annotation <code>daemon-based</code> in zweiter Reihe unterhalb von Communication Management hinzugefügt.\n</li></ul>"}, {"from": "FIG-3bbfc4576980545a", "to": "FIG-8206c96d6df536fd", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Network Management</code>: Annotation <code>daemon-based</code> neu hinzugefügt (Klassifizierung als eigenständiger Systemprozess/Daemon statt rein bibliotheksbasierter Einbindung).\n</li></ul>"}]};
